CREATE OR REPLACE FUNCTION public.sou_desenvolvedor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='desenvolvedor'); $$;
REVOKE ALL ON FUNCTION public.sou_desenvolvedor() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.sou_desenvolvedor() TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.proteger_papel_desenvolvedor() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (CASE WHEN TG_OP='INSERT' THEN NEW.role='desenvolvedor' WHEN TG_OP='DELETE' THEN OLD.role='desenvolvedor' ELSE OLD.role='desenvolvedor' OR NEW.role='desenvolvedor' END) AND current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Perfil reservado à configuração do sistema' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE TRIGGER proteger_desenvolvedor BEFORE INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.proteger_papel_desenvolvedor();
CREATE TABLE public.developer_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), criado_em timestamptz NOT NULL DEFAULT now(), categoria text NOT NULL CHECK(categoria IN ('carregamento','atualizacao','erro','lentidao','seguranca')), origem text NOT NULL, codigo text NOT NULL, mensagem text NOT NULL, duracao_ms integer, reconhecido_em timestamptz);
GRANT SELECT ON public.developer_alerts TO authenticated; GRANT ALL ON public.developer_alerts TO service_role;
ALTER TABLE public.developer_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY developer_only_read ON public.developer_alerts FOR SELECT TO authenticated USING(public.sou_desenvolvedor());
CREATE INDEX developer_alerts_data ON public.developer_alerts(criado_em DESC);
CREATE OR REPLACE FUNCTION public.registrar_aviso_painel(p_codigo text,p_origem text,p_duracao_ms integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_cat text; v_msg text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Faça login' USING ERRCODE='42501'; END IF;
IF p_origem NOT IN ('painel','publicidade','perguntas','anuncios','promocoes','integracoes','mercado','admin') THEN RETURN; END IF;
CASE p_codigo WHEN 'carregamento_falhou' THEN v_cat:='carregamento'; v_msg:='Falha ao carregar dados da tela.'; WHEN 'renderizacao_falhou' THEN v_cat:='erro'; v_msg:='Falha ao exibir uma tela.'; WHEN 'atualizacao_falhou' THEN v_cat:='atualizacao'; v_msg:='Uma solicitação de atualização falhou.'; WHEN 'leitura_parcial' THEN v_cat:='atualizacao'; v_msg:='Leitura concluída com avisos; parte dos dados não foi atualizada.'; WHEN 'resposta_lenta' THEN IF p_duracao_ms IS NULL OR p_duracao_ms<8000 THEN RETURN; END IF; v_cat:='lentidao'; v_msg:='Uma consulta demorou pelo menos 8 segundos.'; ELSE RETURN; END CASE;
PERFORM pg_advisory_xact_lock(hashtextextended('developer-alert-'||p_origem||p_codigo,0));
IF EXISTS(SELECT 1 FROM public.developer_alerts WHERE origem=p_origem AND codigo=p_codigo AND criado_em>now()-interval '1 minute') THEN RETURN; END IF;
INSERT INTO public.developer_alerts(categoria,origem,codigo,mensagem,duracao_ms) VALUES(v_cat,p_origem,p_codigo,v_msg,CASE WHEN p_duracao_ms BETWEEN 0 AND 3600000 THEN p_duracao_ms ELSE NULL END);
END; $$;
REVOKE ALL ON FUNCTION public.registrar_aviso_painel(text,text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.registrar_aviso_painel(text,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.reconhecer_aviso_desenvolvedor(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.sou_desenvolvedor() THEN RAISE EXCEPTION 'Acesso restrito' USING ERRCODE='42501'; END IF; UPDATE public.developer_alerts SET reconhecido_em=now() WHERE id=p_id AND reconhecido_em IS NULL; END; $$;
REVOKE ALL ON FUNCTION public.reconhecer_aviso_desenvolvedor(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reconhecer_aviso_desenvolvedor(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.avisos_operacionais_existentes() RETURNS TABLE(id text,categoria text,origem text,mensagem text,criado_em timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.sou_desenvolvedor() THEN RAISE EXCEPTION 'Acesso restrito' USING ERRCODE='42501'; END IF; RETURN QUERY
SELECT 'job-'||j.id::text,'atualizacao'::text,'Importação'::text,'Uma importação falhou; verifique o processamento da conta.'::text,coalesce(j.finished_at,j.started_at,j.scheduled_at) FROM public.sync_jobs j WHERE j.status IN ('error','failed','erro') AND coalesce(j.finished_at,j.started_at,j.scheduled_at)>now()-interval '7 days'
UNION ALL SELECT 'webhook-'||w.id::text,'atualizacao'::text,'Avisos Mercado Livre'::text,'Falha ao processar um aviso recebido do Mercado Livre.'::text,w.recebido_em FROM public.ml_webhook_events w WHERE w.status='erro' AND w.recebido_em>now()-interval '7 days'
UNION ALL SELECT 'cron-'||c.runid::text,'atualizacao'::text,'Rotina programada'::text,'Uma rotina programada falhou.'::text,c.start_time FROM cron.job_run_details c WHERE c.status='failed' AND c.start_time>now()-interval '7 days'
ORDER BY 5 DESC LIMIT 100; END; $$;
REVOKE ALL ON FUNCTION public.avisos_operacionais_existentes() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.avisos_operacionais_existentes() TO authenticated;
CREATE OR REPLACE FUNCTION public.limpar_avisos_desenvolvedor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.developer_alerts WHERE criado_em<now()-interval '30 days'; RETURN NULL; END; $$;
CREATE TRIGGER developer_alerts_retention AFTER INSERT ON public.developer_alerts FOR EACH STATEMENT EXECUTE FUNCTION public.limpar_avisos_desenvolvedor();